  .js-ready .ov-te-scroll:not(.is-visible) .ov-te-zeile-innen { opacity: 0; transform: translate3d(0, 0.9em, 0); }
}

/* ---------- PfadZeichnen: SVG-Linien zeichnen sich beim Eintritt ---------- */
.ov-pfad :is(path, line, polyline, polygon, circle, ellipse, rect)[pathLength="1"] {
