        </div>
      </div>
      {karte && f.darstellung === "karte" && (
        <div className="mb-8">
          <KarteDach projekte={basisListe} region={f.region} onRegion={(r) => setze("region", r)} />
        </div>
      )}

      {liste.length ? (
        <ul className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">
          {liste.map((p) => (
            <li key={p.id}>
              <ProjektKarte
                projekt={p}
