python - <<'EOF'
p='src/components/Boerse/BoerseListe.js'
s=open(p,encoding='utf-8').read()
rep=[
('''import { useEffect, useMemo, useState } from "react";''','''import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";'''),
('''import { eingabe, auswahlfeld } from "@/components/Portal/felder";''','''import { eingabe, auswahlfeld } from "@/components/Portal/felder";
import Button from "@/components/ui/Button";

const KURVE = "cubic-bezier(0.22, 1, 0.36, 1)";

/**
 * FLIP-Übergang für die Kartenliste: Bleibende Karten gleiten an ihren neuen Platz,
 * neu hinzukommende blenden gestaffelt ein. Nur transform/opacity (Web Animations API),
 * nichts beim ersten Rendern, nichts bei reduzierter Bewegung, nur im sichtbaren Bereich.
 */
function useFlipListe(schluessel) {
  const ref = useRef(null);
  const positionen = useRef(null);
  useLayoutEffect(() => {
    const ul = ref.current;
    const alt = positionen.current;
    const neu = new Map();
    if (ul) for (const li of ul.children) neu.set(li.dataset.id, { x: li.offsetLeft, y: li.offsetTop });
    positionen.current = neu;
    if (!ul || !alt || typeof ul.animate !== "function") return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const hoehe = window.innerHeight;
    let neuIndex = 0;
    for (const li of ul.children) {
      const r = li.getBoundingClientRect();
      if (r.bottom < -40 || r.top > hoehe + 40) continue; // außerhalb des Bildes: nichts animieren
      const a = alt.get(li.dataset.id);
      const n = neu.get(li.dataset.id);
      if (a) {
        const dx = a.x - n.x;
        const dy = a.y - n.y;
        if (dx || dy) li.animate([{ transform: `translate3d(${dx}px, ${dy}px, 0)` }, { transform: "none" }], { duration: 460, easing: KURVE });
      } else {
        li.animate(
          [{ opacity: 0, transform: "translate3d(0, 14px, 0) scale(0.97)" }, { opacity: 1, transform: "none" }],
          { duration: 380, delay: Math.min(neuIndex++, 6) * 50, easing: KURVE, fill: "backwards" }
        );
      }
    }
  }, [schluessel]);
  return ref;
}'''),
('''  const aktiveFilter = ["typ", "land", "phase", "mwpMin", "mwpMax", "region"].filter((k) => f[k]).length;''','''  const aktiveFilter = ["typ", "land", "phase", "mwpMin", "mwpMax", "region"].filter((k) => f[k]).length;
  const listeRef = useFlipListe(liste.map((p) => p.id).join("|"));
  // Trefferzahl: kurzer Einblend-Impuls bei jeder Änderung (Feedback auf den Filter)
  const anzahl = (
    <span key={liste.length} className="ov-num font-semibold text-ink-900 motion-safe:animate-ov-einblenden">{liste.length}</span>
  );'''),
('''<p className="text-[13.5px] text-ink-500" aria-live="polite"><span className="ov-num font-semibold text-ink-900">{liste.length}</span> {liste.length === 1 ? "Projekt" : "Projekte"}</p>''','''<p className="text-[13.5px] text-ink-500" aria-live="polite">{anzahl} {liste.length === 1 ? "Projekt" : "Projekte"}</p>'''),
('''<p className="hidden text-[14px] text-ink-600 md:block" aria-live="polite"><span className="ov-num font-semibold text-ink-900">{liste.length}</span> {liste.length === 1 ? "Projekt" : "Projekte"} gefunden</p>''','''<p className="hidden text-[14px] text-ink-600 md:block" aria-live="polite">{anzahl} {liste.length === 1 ? "Projekt" : "Projekte"} gefunden</p>'''),
('''        <div className="mb-8">
          <KarteDach''','''        <div className="ov-tab-panel mb-8">
          <KarteDach'''),
('''        <ul className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">
          {liste.map((p) => (
            <li key={p.id}>''','''        <ul ref={listeRef} className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">
          {liste.map((p) => (
            <li key={p.id} data-id={p.id}>'''),
('''        <div className="flex flex-col items-center rounded-3xl border border-dashed border-ink-200 bg-white/60 px-6 py-14 text-center">''','''        <div className="ov-tab-panel flex flex-col items-center rounded-3xl border border-dashed border-ink-200 bg-white/60 px-6 py-14 text-center">'''),
('''            {portal ? "Passen Sie die Filter an – oder hinterlegen Sie ein Suchprofil, dann melden wir uns, sobald ein passendes Projekt eingeht." : "Passen Sie die Filter an oder legen Sie als Investor ein Suchprofil an – wir melden uns, sobald ein passendes Projekt eingeht."}
          </p>''','''            {portal ? "Passen Sie die Filter an – oder hinterlegen Sie ein Suchprofil, dann melden wir uns, sobald ein passendes Projekt eingeht." : "Passen Sie die Filter an oder legen Sie als Investor ein Suchprofil an – wir melden uns, sobald ein passendes Projekt eingeht."}
          </p>
          {/* Leere Trefferliste ist ein Einstieg, keine Sackgasse: Filter lösen oder Suchprofil anlegen */}
          <div className="mt-6 flex flex-col gap-3 sm:flex-row">
            {aktiveFilter > 0 && (
              <Button variant="secondary" onClick={() => setF((x) => ({ ...LEER, sortierung: x.sortierung, ansicht: x.ansicht, darstellung: x.darstellung }))}>
                Filter zurücksetzen
              </Button>
            )}
            {!portal && (
              <Button href="/registrieren?rolle=investor" pfeil>
                Suchprofil anlegen
              </Button>
            )}
          </div>'''),
]
for a,b in rep:
    assert a in s, a[:70]
    s=s.replace(a,b,1)
open(p,'w',encoding='utf-8').write(s)
