/* Lokale Bewegungen der Projektbörse (Karte). Nur transform/opacity.
   Ohne JS und bei reduzierter Bewegung steht alles sofort. */

.blase {
  transform-box: fill-box;
  transform-origin: center;
}

@keyframes blaseEin {
  from { opacity: 0; transform: scale(0.35); }
  to { opacity: 1; transform: none; }
}
@keyframes puls {
  from { opacity: 0.55; transform: scale(1); }
  to { opacity: 0; transform: scale(1.9); }
}

@media (prefers-reduced-motion: no-preference) {
  /* Hero-Bühne: beim Laden, reines CSS */
  .laden .blase {
    animation: blaseEin 560ms cubic-bezier(0.34, 1.4, 0.64, 1) both;
    animation-delay: calc(var(--ov-delay, 0ms) + var(--i, 0) * 80ms);
  }
  /* Bedienbare Karte: beim Eintritt (RevealObserver setzt .is-visible) */
  :global(.js-ready) :global(.ov-reveal):not(:global(.is-visible)) .blase {
    opacity: 0;
    transform: scale(0.35);
  }
  :global(.is-visible) .blase {
    animation: blaseEin 520ms cubic-bezier(0.34, 1.4, 0.64, 1) both;
    animation-delay: calc(var(--ov-delay, 0ms) + var(--i, 0) * 60ms);
  }
  /* Auswahl-Feedback: ein Ring läuft einmal aus */
  .puls {
    transform-box: fill-box;
    transform-origin: center;
    animation: puls 720ms cubic-bezier(0.22, 1, 0.36, 1) both;
  }
}
@media (prefers-reduced-motion: reduce) {
  .puls { display: none; }
}
EOF
